('5a4e0011-0000-4000-8000-000000000001', '5a4e0010-0000-4000-8000-000000000001', '5a4e0000-0000-4000-8000-000000030004', 'Merhaba, referans üzerine yazıyorum. 29.09 günü İstanbul''da kurumsal var; o gün uygun musunuz? Bütçe aralığımızı da yazdım.', 'text', NULL, pg_temp.t(1368.23), pg_temp.t(1346.53)),
('5a4e0011-0000-4000-8000-000000000002', '5a4e0010-0000-4000-8000-000000000001', '5a4e0000-0000-4000-8000-000000010031', 'Merhaba, teşekkürler. 29.09 tarihi şu an için müsait. Detayları konuşup size özel bir teklif hazırlayayım; mekan ve saat bilgisini de alabilir miyim?', 'text', NULL, pg_temp.t(1301.93), pg_temp.t(1282.62)),
('5a4e0011-0000-4000-8000-000000000003', '5a4e0010-0000-4000-8000-000000000001', '5a4e0000-0000-4000-8000-000000030004', 'Harika. Program akışını yarın paylaşırım. Bir de ödeme koşullarınızı öğrenebilir miyim?', 'text', NULL, pg_temp.t(1300.10), pg_temp.t(1290.71)),
